with valid as (select id, store_id, product_id, quantity, case when quantity >= 270 then 'High' when quantity >= 106 then 'Medium' else 'Low' end as quantity_tier, round(quantity, 2) as quantity_rounded from inventory where last_restock >= date '2023-07-17'), latest as (select id, store_id from (select *, rank() over (partition by store_id, product_id order by quantity desc nulls last) as latest_rank from valid) t where latest_rank = 1), with_dims as (select e.*, b.store_name, b.sqft, b.city from latest e left join stores b on e.store_id = b.id), deduped as (select *, row_number() over (partition by city order by sqft desc, id) as dedup_rank from with_dims qualify dedup_rank = 1) select case when sqft >= 14614 then 'HIGH' else 'LOW' end as sqft_tier, store_id, count_if(city = 'Chiang Mai') as chiang_mai_events, sum(sqft) filter (where city = 'Berlin') as berlin_total_sqft, round(avg(sqft), 2) as avg_sqft from deduped group by case when sqft >= 14614 then 'HIGH' else 'LOW' end, store_id order by berlin_total_sqft;
